#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include "systolic_stub.h"

/* generated by ICDeCompiler */
void matmul_rect(int16_t A[4][6], int16_t B[6][8], int32_t C[4][8]);

int main(void) {
    int16_t A[4][6], B[6][8];
    int32_t C[4][8];
    int32_t ref[4][8];

    for (int i = 0; i < 4; i++)
        for (int k = 0; k < 6; k++)
            A[i][k] = (int16_t)(i * 3 + k + 1);

    for (int k = 0; k < 6; k++)
        for (int j = 0; j < 8; j++)
            B[k][j] = (int16_t)(k - j * 2);

    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 8; j++)
            C[i][j] = 0;

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 8; j++) {
            int32_t acc = 0;
            for (int k = 0; k < 6; k++)
                acc += (int32_t)A[i][k] * (int32_t)B[k][j];
            ref[i][j] = acc;
        }
    }

    matmul_rect(A, B, C);

    int mismatches = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 8; j++) {
            if (C[i][j] != ref[i][j]) {
                if (mismatches < 5)
                    printf("mismatch at [%d][%d]: got %d, expected %d\n",
                           i, j, C[i][j], ref[i][j]);
                mismatches++;
            }
        }
    }

    if (mismatches == 0) {
        printf("OK: rectangular matmul matches reference\n");
        return 0;
    }
    printf("FAIL: %d mismatches\n", mismatches);
    return 1;
}